import{_ as e,o,c as r,ae as t}from"./chunks/framework.BajMXG5H.js";const p=JSON.parse('{"title":"よくある質問","description":"","frontmatter":{},"headers":[],"relativePath":"ja/reference/faq.md","filePath":"ja/reference/faq.md"}'),l={name:"ja/reference/faq.md"};function i(d,a,c,h,n,s){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to &quot;よくある質問&quot;">​</a></h1><h2 id="orchestraは無料ですか" tabindex="-1">Orchestraは無料ですか？ <a class="header-anchor" href="#orchestraは無料ですか" aria-label="Permalink to &quot;Orchestraは無料ですか？&quot;">​</a></h2><p>はい。Orchestraは完全に無料でオープンソースです。</p><h2 id="データはどこかに送信されますか" tabindex="-1">データはどこかに送信されますか？ <a class="header-anchor" href="#データはどこかに送信されますか" aria-label="Permalink to &quot;データはどこかに送信されますか？&quot;">​</a></h2><p>いいえ。全てのデータはローカルマシンに保存されます。hookサーバーは<code>localhost:3008</code>で動作し、ローカルのClaude Codeセッションからの接続のみ受け付けます。外部サーバーへのデータ送信は一切ありません。</p><h2 id="どのaiコーディングエージェントに対応していますか" tabindex="-1">どのAIコーディングエージェントに対応していますか？ <a class="header-anchor" href="#どのaiコーディングエージェントに対応していますか" aria-label="Permalink to &quot;どのAIコーディングエージェントに対応していますか？&quot;">​</a></h2><p>現在、Hooks機能を通じて<strong>Claude Code</strong>をサポートしています。将来的に他のエージェントへの対応も検討しています。</p><h2 id="システム要件は" tabindex="-1">システム要件は？ <a class="header-anchor" href="#システム要件は" aria-label="Permalink to &quot;システム要件は？&quot;">​</a></h2><ul><li>macOS 11.0+（Big Sur以降）</li><li>Apple Silicon（M1/M2/M3/M4）</li><li>tmux（セッションジャンプ用）</li><li>Claude Code（インストール済み）</li></ul><h2 id="アンインストール方法は" tabindex="-1">アンインストール方法は？ <a class="header-anchor" href="#アンインストール方法は" aria-label="Permalink to &quot;アンインストール方法は？&quot;">​</a></h2><ol><li>Orchestraが実行中の場合は終了</li><li><code>/Applications</code>から<code>Orchestra.app</code>を削除</li><li><code>~/.claude/settings.json</code>からhook設定を削除</li></ol><h2 id="tmuxなしでも使えますか" tabindex="-1">tmuxなしでも使えますか？ <a class="header-anchor" href="#tmuxなしでも使えますか" aria-label="Permalink to &quot;tmuxなしでも使えますか？&quot;">​</a></h2><p>tmuxなしでもセッションの監視は可能ですが、「セッションにジャンプ」機能はtmuxが必要です。tmux外で実行されているセッションはダッシュボードに表示されますが、Jumpボタンは使用できません。</p><h2 id="claude-codeのチーム機能に対応していますか" tabindex="-1">Claude Codeのチーム機能に対応していますか？ <a class="header-anchor" href="#claude-codeのチーム機能に対応していますか" aria-label="Permalink to &quot;Claude Codeのチーム機能に対応していますか？&quot;">​</a></h2><p>はい。Orchestraはマシン上の全てのClaude Codeセッションからのhookイベントを監視します。チームセッションやサブエージェントのアクティビティも含まれます。</p>',15)])])}const m=e(l,[["render",i]]);export{p as __pageData,m as default};
